\begin{corollary}\label{compression:cost-one}
A countable p.m.p. Borel equivalence relation on a standard probability
space, all of whose classes are infinite, has cost at least one.
\end{corollary}

\begin{proposition}\label{models:transfer}
Let $V_k$ be finite exact right $A$-sets, with $n_k=|V_k|\to\infty$,
such that for every fixed $g\in A\setminus\{1\}$,
\begin{equation}
 \frac{|\{v\in V_k:vg=v\}|}{n_k}\longrightarrow0.
 \label{models:fixed-points}
\end{equation}
For the free Bernoulli action on $X$ from
Section~\ref{actions:section}, whose cost agrees with the full product
action on $X_0=[0,1]^\Gamma$, one has
\[
 \delta_X\ge\limsup_{k\to\infty}
 \frac{\operatorname{rk}(D_{V_k})}{n_k}.
\]
\end{proposition}

\begin{proposition}\label{models:sequence}
Put $K=e^{96}96^{99}/95^{95}$. Fix
\[
 0<\alpha<1/200,\qquad K\alpha^3<1/2.
\]
There exists a sequence of finite exact right $A$-sets $V_k$, with
$n_k=|V_k|\to\infty$, satisfying \eqref{models:fixed-points} and
\begin{align}
 |N(T)|&>96|T|
 &&(T\subseteq V_k,\ 1\le |T|\le\alpha n_k),
 \label{models:expansion}\\
 b(V_k)&=o(n_k).
 \label{models:bad-rows}
\end{align}
\end{proposition}

\begin{lemma}
\label{actions:normal-form}
The factors $A$ and $B$ embed in $\Gamma$ with intersection $J$.
If $g_1,\ldots,g_n$ lie alternately in $A\setminus J$ and
$B\setminus J$, then $g_1\cdots g_n\notin J$ for $n\geq1$, and
$g_1\cdots g_n$ belongs to neither factor for $n\geq2$.
The group $J$ is free on $b_1,\ldots,b_{99},w$; in particular it is
infinite.  The group $\Gamma$ is countably infinite and generated by
$a,b_1,\ldots,b_{99},t$.
\end{lemma}

\begin{lemma}
\label{actions:height}
There is a homomorphism $\chi:\Gamma\to\mathbb Z$ with
\[
 \chi(a)=1,\qquad \chi(b_i)=\chi(t)=0.
\]
It satisfies $\chi(u_i)=i$ and $\chi(w)=100$.
For every positive integer $M$, the action on
\[
 Y_M=X\times\mathbb Z/M\mathbb Z,
 \qquad \nu_M=\mu\times\text{uniform measure},
\]
defined by
\begin{equation}
 \label{actions:product-action}
 (x,r)g=(xg,r+\chi(g)\bmod M)
\end{equation}
is free and p.m.p. on a standard Borel probability space.
\end{lemma}

\begin{lemma}
\label{actions:small-marker}
For every $0<p<1$ and every positive integer $M$, there is a Borel
set $C_p\subseteq Y_M$ of measure $p$ meeting every
$\langle t\rangle$-orbit.  The graphing consisting of $t$ on all
of $Y_M$ and $b_1,\ldots,b_{99},w$ restricted to $C_p$ generates
$\mathcal R_B$ and has cost $1+100p$.
\end{lemma}

\begin{proposition}
\label{actions:low}
For every integer $M>100$, the free p.m.p. action
$\Gamma\curvearrowright(Y_M,\nu_M)$ of
\eqref{actions:product-action} satisfies
\[
 \operatorname{Cost}(\mathcal R_{\Gamma\curvearrowright Y_M})
 \leq1+\frac{99}{M}.
\]
\end{proposition}

\begin{proposition}\label{prop:sequences}
Let $L$ be a nonzero separable Hilbert space, let $D\subseteq\B(L)$ be a
unital norm-separable $C^*$-algebra with $Z(D)=\C\id_L$, and let
$P,Q\subseteq D$ be unital $C^*$-subalgebras containing $\id_L$.
On $H=\bigoplus_{n\ge1}L$, define
\begin{equation}\label{eq:sequence-definition}
\E_D(P)=\{(x_n)_{n\ge1}:x_n\in D,\ x_n\to p\in P\text{ in norm}\},
\end{equation}
and define $\E_D(Q)$ similarly. Then:
\begin{enumerate}
\item These are unital norm-separable $C^*$-algebras with common identity,
and
\begin{equation}\label{eq:distance-equality}
\KK(\E_D(P),\E_D(Q))=\KK(P,Q).
\end{equation}
\item If a unitary conjugates $\E_D(P)$ onto $\E_D(Q)$, there are unitaries
$U_n\in\B(L)$ with $U_nDU_n^*=D$ such that, for every $b\in Q$, some
$p_b\in P$ satisfies
\begin{equation}\label{eq:pointwise-normalizers}
\norm{b-U_np_bU_n^*}\longrightarrow0.
\end{equation}
The same sequence $(U_n)$ works for every $b$.
\item The two algebras have the same commutant, and hence the same
von Neumann closure.
\end{enumerate}
\end{proposition}

\begin{lemma}\label{lem:tree}
For every $0<t<1$, there is a unitary representation $\pi_t:G\to\B(K)$
such that, with $r=\sqrt{1-t^2}$,
\begin{align}
\inner{\pi_t(s_i)\delta_e}{\delta_e}&=t\quad(i\ge1),\label{eq:coefficient}\\
\sup_{g\in G}\norm{\pi_t(g)-\lambda(g)}&\le c(t),\qquad
c(t)=2(1-r)+\frac{t}{1-t}+t.\label{eq:uniform}
\end{align}
In particular, $c(t)\to0$ as $t\downarrow0$.
\end{lemma}

\begin{lemma}[Absorption]\label{lem:absorption}
Let $\sigma$ be a unitary representation of $G$ on a nonzero Hilbert space
$J$. The operator
\[
W_\sigma(\delta_x\otimes v)=\delta_x\otimes\sigma(x)v
\quad(x\in G,\ v\in J)
\]
is unitary on $K\otimes J$ and satisfies
\begin{equation}\label{eq:absorption}
W_\sigma(\lambda(g)\otimes\id_J)W_\sigma^*
=\lambda(g)\otimes\sigma(g)\quad(g\in G).
\end{equation}
\end{lemma}

\begin{lemma}\label{lem:ambient}
The algebra $D$ in \eqref{eq:D} has scalar center, and
\begin{equation}\label{eq:commutant}
D'=\{Y\otimes\id_K:Y\in\lambda(G)'\}.
\end{equation}
There is a unitary $W\in\B(L)$ such that
\begin{equation}\label{eq:close-W}
WP_0W^*=P_t,\qquad \norm{W-\id_L}\le c(t).
\end{equation}
\end{lemma}

\begin{lemma}\label{lem:good-inclusion}
The inclusion $P_0\subseteq D$ has the spatial tensor-norm identity.
\end{lemma}

\begin{lemma}\label{lem:free-norm}
For every positive integer $m$,
\begin{equation}\label{eq:free-norm}
\norm{\sum_{i=1}^m\lambda(s_i)}\le2\sqrt m.
\end{equation}
\end{lemma}

\begin{lemma}\label{lem:bad-inclusion}
For every $0<t<1$, the inclusion $P_t\subseteq D$
fails the spatial tensor-norm identity.
\end{lemma}

\begin{lemma}\label{abs:prime-block-map}
If $r$ and $s$ are relatively prime, there is a unital homomorphism
$I(r,s)\to I(p,p+1)$ for some $p\ge2$.
\end{lemma}

\begin{lemma}\label{abs:approximate-retraction}
Let $D\subset L$ be a unital inclusion with $D$ nuclear.  Given a
finite subset $G\subset D$ and $\eps>0$, there is a \cpc map
$R:L\to D$ with $\|R(d)-d\|<\eps$ for $d\in G$.
\end{lemma}

\begin{proposition}\label{prop:Z-map}
Let $A$ be a nonzero separable nuclear $C^*$-algebra satisfying
\textup{(C)}, and fix any free ultrafilter $\omega$ on $\mathbb N$.
Then there is a unital homomorphism $\Z\to F_\omega(A)$.
\end{proposition}

\begin{lemma}\label{abs:connected-unitaries}
The unitary groups of $\Z$ and $\Z\otimes\Z$ are path connected.
If $q:D\to D/J$ is a unital quotient map, every unitary in the
identity component of $\mathcal U(D/J)$ lifts to a unitary in $D$.
\end{lemma}

\begin{lemma}\label{abs:finite-unitary-criterion}
Let $A$ be a separable $C^*$-algebra, and suppose there is a unital
homomorphism $\varphi:\Z\to F_\omega(A)$.
For finite sets $F\subset A$, $G\subset A\otimes\Z$, and
$\eps>0$, there is a unitary $u\in A^{\sim}\otimes\Z$ such that
\begin{equation}\label{abs:unitary-criterion}
 \|[u,a\otimes1]\|<\eps\quad(a\in F),\qquad
 \dist(u^*bu,A\otimes1)<\eps\quad(b\in G).
\end{equation}
\end{lemma}

\begin{proposition}\label{prop:absorption}
If a separable $C^*$-algebra $A$ admits a unital homomorphism
$\Z\to F_\omega(A)$, then $A\cong A\otimes\Z$.

\end{proposition}

\begin{lemma}\label{cen:elementary-tensor}
Let $D$ and $C$ be $C^*$-algebras.  Every nonzero closed two-sided ideal
of $D\otimes C$ contains a nonzero tensor $a\otimes b$ with
$a\in D_+$ and $b\in C_+$.
\end{lemma}

\begin{lemma}\label{cen:nuclear-tensor-ideals}
If $D$ is nuclear and $C$ is arbitrary, every closed two-sided ideal
$J\subset D\otimes C$ is generated by the positive elementary tensors
that it contains.
\end{lemma}

\begin{proposition}\label{prop:central-filler}
Let $A$ be a separable nuclear $C^*$-algebra satisfying
\textup{(C)}.
For each $p\ge2$ there are a \cpc order-zero map
$\alpha:M_p\to A_\omega\cap A'$, with $h=\alpha(1)$, and an element
$S\in A_\omega\cap A'$ such that
\begin{equation}\label{cen:filler-relations}
 \alpha(e_{11})S=S,\qquad S^*S a=(1-h)a\quad(a\in A).
\end{equation}
One can choose $\|S\|\le2$.  In the second equation the expression
$(1-h)a$ is computed in the unitization of $A_\omega$ and belongs to
$A_\omega$.
\end{proposition}

\begin{proposition}[An adaptive rank gap]\label{prop:rankgap}
For every fixed $k\ge2$ there is a \cpc order-zero map
$\zeta^k:M_k\to A_\omega\cap A'$ with weight $H$ such that, for every
test $(a,\eps)$, if
\begin{equation}\label{cmp:u-y}
 u^k(a)=(1-f(H))a,
 \qquad y^k(a)=g(\zeta^k)(e_{11})^2a,
\end{equation}
there is $r_{a,\eps}^k\in A_\omega$ satisfying
\begin{equation}\label{cmp:bounded-comparison}
 (u^k(a)-\eps)_+
   =(r_{a,\eps}^k)^*y^k(a)r_{a,\eps}^k,
 \qquad \|r_{a,\eps}^k\|^2\le32/\eps.
\end{equation}
In particular the witness bound is independent of $k$.
\end{proposition}

\begin{proposition}[Infinitely many central slots]\label{prop:slots}
For every $p\ge2$ there are a \cpc order-zero map
$\alpha:M_p\to A_\omega\cap A'$, with weight $h=\alpha(1)$,
and contractions $s_j\in A_\omega\cap A'$ for $j\ge1$ such that,
putting $P=s_1$, one has
\begin{equation}\label{cmp:slot-relations}
 P\ge0,\qquad s_i^*s_j=\delta_{ij}P^2,
 \qquad \alpha(e_{11})s_j=s_j.
\end{equation}
For every test $(a,\eps)$ there is $r_{a,\eps}\in A_\omega$ with
\begin{equation}\label{cmp:slot-comparison}
 ((1-h)a-\eps)_+
       =r_{a,\eps}^*(P^2a)r_{a,\eps},
 \qquad \|r_{a,\eps}\|^2\le64/\eps.
\end{equation}
No centrality is asserted or needed for these comparison witnesses.
\end{proposition}

\begin{theorem}
\label{ext:thm:divisibility}
Let $A$ be a simple exact non-elementary $C^*$-algebra with strict
comparison as in Equation~\eqref{ext:eq:comparison}.
For every $x\in\Cu(A)$ and integer $N\ge1$, there exists
$u\in\Cu(A)$ such that $Nu\le x\le(N+1)u$.
\end{theorem}

\begin{corollary}[Condition (C) from comparison]
\label{ext:cor:condition-C}
Let $A$ be a simple exact non-elementary $C^*$-algebra with strict
comparison in the sense of Equation~\eqref{ext:eq:comparison}.
Then $\Cu(A)$ satisfies condition \textup{(C)}.
\end{corollary}

\begin{theorem}[Simple comparison and absorption]
\label{ext:thm:main}
Let $A$ be a separable simple nuclear non-elementary $C^*$-algebra.
If $A$ has strict comparison in the sense of
Equation~\eqref{ext:eq:comparison}, then $A\cong A\otimes_{\min}\Z$.
\end{theorem}

\begin{lemma}[Joining two matrix cones]\label{lem:join}
Let $B$ be a $C^*$-algebra, and let $\phi_1,\phi_2:M_k\to B$ be
\cpc order-zero maps with commuting ranges.  Set $h_i=\phi_i(1)$.
There is a \cpc order-zero map $\phi:M_k\to
C^*(\phi_1(M_k),\phi_2(M_k))$ such that
\begin{equation}\label{loc:join-weight}
 \phi(1)=1-(1-h_1)(1-h_2)=h_1+h_2-h_1h_2.
\end{equation}
Its weight dominates both $h_1$ and $h_2$.  If both original maps commute
with a subset of an ambient algebra, the joined map also commutes with
that subset.
\end{lemma}

\begin{lemma}[Filling bounded traces]\label{loc:bounded-fill}
Let $D\subseteq A$ be hereditary, $k\ge2$, $F\subset D$ finite, and
$\mathcal P\subset D$ a finite set of positive contractions.  For every
$\rho>0$ there is a \cpc map $\mu:M_k\to D$ such that, for all matrix
units $e_{ij},e_{rs}$ and all $x\in F$,
\begin{align}
 \|[\mu(e_{ij}),x]\|_{2,T_{\leq1}(D)}&<\rho,\label{loc:fill-comm}\\
 \|\mu(e_{ij})\mu(e_{rs})-\mu(1)\mu(e_{ij}e_{rs})
       \|_{2,T_{\leq1}(D)}&<\rho,\label{loc:fill-oz}\\
 \sigma\bigl(a^{1/2}(1-\mu(1))a^{1/2}\bigr)&<\rho
       \quad(a\in\mathcal P,\ \sigma\in T_{\leq1}(D)).
       \label{loc:fill-trace}
\end{align}
\end{lemma}

\begin{lemma}\label{norm:prototype}
For this finite word model there is a positive contractive seed
\(s\in A\) with \(\sigma(s)\ne0\), whose support \(P=p_s\) satisfies
\begin{align}
 PxP&\ge(\gamma/4)P,                                      \label{norm:positive-compression}\\
 \big\|(Pb_i^*b_jP)_{i,j=1}^m-I_m\otimes P\big\|
      &\le\eta^2/4,                                     \label{norm:local-gram}\\
 \big\|(Pr_i(a)^*r_j(a)P)_{l_i,l_j<d}\big\|
      &\le\eta^2/4\qquad(a\in F).                        \label{norm:local-residual}
\end{align}
Every positive element in \(\her(s)\) has a support on which the
same three estimates hold.
\end{lemma}

\begin{lemma}\label{norm:separated-cover}
Assume that $A$ satisfies \textup{(C)}. Suppose that positive
contractions \(s_1,\ldots,s_m\in A\) have
nonvanishing loci covering \(\mathcal K(x,\gamma)\).
For each pair \(i\ne j\), prescribe a finite set
\(\mathcal E_{ij}\subset\widetilde A\), and let \(\delta>0\).
There are positive contractions \(t_i\in\her(s_i)\), with supports
\(Q_i=p_{t_i}\), such that
\begin{align}
 \max_i\|\sigma(t_i)\|&=1
                 &&(\sigma\in\mathcal K(x,\gamma)),       \label{norm:retained-cover}\\
 \|Q_i z Q_j\|&\le\delta
                 &&(i\ne j,\ z\in\mathcal E_{ij}).        \label{norm:cross-compressions}
\end{align}
\end{lemma}

\begin{lemma}\label{norm:finite-stage}
Assume that $A$ satisfies \textup{(C)}. Let \(x\in A\) be a positive
contraction, \(\gamma>0\), \(k\ge2\),
\(F\subset A\) a finite set of selfadjoint contractions,
\(d\ge1\), and \(0<\eta<1\).
There is a \cpc map \(V:M_k\to A\) such that
\begin{align}
 \|V(z)V(w)\|&\le\eta^2
   &&(z,w\in(M_k)_+,\ \|z\|,\|w\|\le1,\ zw=0),            \label{norm:order-zero-error}\\
 \|[a,V(z)]\|&\le2\eta+2/d
   &&(a\in F,\ \|z\|\le1),                               \label{norm:central-error}\\
 \|\sigma(xV(1))\|&\ge\gamma^2/32
   &&(\sigma\in\mathcal K(x,\gamma)).                    \label{norm:finite-visibility}
\end{align}
\end{lemma}

\begin{lemma}
\label{lem:comparison-convention}
For any $C^*$-algebra $A$, strict comparison in the sense of
Equation~\eqref{ext:eq:comparison} is equivalent to almost unperforation
of $\Cu(A)$.
\end{lemma}

\begin{lemma}[Integer spectral rounding]
\label{ext:lem:rounding}
Let $B$ be a stable $C^*$-algebra, $c\in B_+$, and let $L$ be an
integer greater than $\|c\|$. Put
\[
 w=\sum_{i=1}^L[(c-i)_+]\in\Cu(B).
\]
For every lower-semicontinuous extended trace $\tau$, writing
$\varphi=d_\tau$, one has
\begin{equation}
\label{ext:eq:rounding}
 \varphi(w)\le\tau(c)\le\varphi(w)+d_\tau(c).
\end{equation}
\end{lemma}

\begin{lemma}[Two-support shrinking]\label{lem:shrinking}
There is a numerical constant $0<c<1$ with the following property for
every $C^*$-algebra $A$ satisfying \textup{(C)}.  If $a,b\in A$ are positive
contractions and $z\in\widetilde A$ satisfies
$\|p_a z p_b\|\le1$, there are positive contractions
$a'\in\her(a)$ and $b'\in\her(b)$ such that
\begin{equation}\label{shr:conclusion}
 \|p_{a'}z p_{b'}\|\le c
\end{equation}
and, for every irreducible representation $\sigma$ of $A$,
\begin{equation}\label{shr:visibility}
 \max\{\|\sigma(a)\|,\|\sigma(b)\|\}\ge\tfrac12
 \quad\Longrightarrow\quad
 \sigma(a')\ne0\ \text{or}\ \sigma(b')\ne0.
\end{equation}
The support norms are computed in the bidual, or equivalently in the
universal representation.
\end{lemma}

\begin{lemma}[Cuntz regularity]
\label{lem:C}
Under the hypothesis of Corollary~\ref{cor:canonical}, the semigroup
$\Cu(A)$ satisfies condition \textup{(C)}, namely
Equations~\eqref{eq:pre:au}--\eqref{eq:pre:div}.
\end{lemma}

\begin{lemma}
\label{lem:support}
Let \(K=K^*\) be a bounded operator on a Hilbert space, let \(s\ge0\)
be bounded, and let \(\lambda\in\R\). On the support of
\[
 b=s[s(\lambda-K)s]_+s
\]
the compression of \(K\) is at most \(\lambda\).
If \(b=0\), then \(s(\lambda-K)s\le0\).
\end{lemma}

\begin{proposition}[Bounded-trace matrix cones]\label{prop:bounded-trace}
Fix $k\geq2$ and put
\[
 L=(20k)^2,\qquad C_k=1+4L.
\]
Let $F\subset D$ be a finite set of selfadjoint contractions, let
$\mathcal P\subseteq F$ consist of positive contractions, and let
$0<\delta<1$.  For every $\varepsilon>0$ there is a \cpc order-zero map
$V:M_k\to D$ such that, for every $\tau\in T_{\leq1}(D)$,
\begin{align}
 \sup_{\|x\|\leq1}\|[a,V(x)]\|_{2,\tau}
 &<\varepsilon &&(a\in F),\label{tr:central-target}\\
 \tau(aV(1))
 &\geq \frac\delta3\tau(a)-C_k\delta^{3/2}-\varepsilon
 &&(a\in\mathcal P).\label{tr:mass-target}
\end{align}
In particular, $k$ is fixed before the accuracy is chosen; no bound on the
number of nuclear approximation summands is required.
\end{proposition}

\begin{proposition}[Uniform approximately invariant unitaries]\label{prop:uniform-unitaries}
For every finite set \(H\subset G\), every \(\eps>0\), and every
integer \(m\geq1\), there are \(t>0\) and a self-adjoint element
\(Q\in C\) such that \(V=\exp(\iu tQ)\) satisfies
\begin{align}
 \sup_{\varphi\in\T(C)}
 \|\bar\alpha_h(V)-V\|_{2,\varphi}
 &<\eps &&(h\in H), \label{eq:uniform-unitary-invariance}\\
 \sup_{\varphi\in\T(C)}|\varphi(V^\ell)|
 &<\eps &&(1\leq\ell\leq m).
 \label{eq:uniform-unitary-moments}
\end{align}
\end{proposition}

\begin{lemma}[Square-root perturbation bound]\label{lem:square-root-trace}
If \(S,T\) are positive matrices of the same size, then
\[
 \|S^{1/2}-T^{1/2}\|_{\HS}^{\,2}\leq\|S-T\|_1.
\]
\end{lemma}

\begin{lemma}[Coordinate selection]\label{lem:coordinate}
If \(x=[(x_j)]\in A^\omega\) has a bounded representative, then
\begin{align}
 \sup_{\tau\in\T_\omega(A)}\|x\|_{2,\tau}
   &=\lim_{j\to\omega}\sup_{\sigma\in\T(A)}\|x_j\|_{2,\sigma},
       \label{eq:coordinate-two}\\
 \sup_{\tau\in\T_\omega(A)}|\tau(x)|
   &=\lim_{j\to\omega}\sup_{\sigma\in\T(A)}|\sigma(x_j)|.
       \label{eq:coordinate-trace}
\end{align}
Consequently, finitely many such tests can be realized simultaneously
at a single coordinate with any prescribed positive slack above their
ultralimit bounds.
\end{lemma}

\begin{proposition}[A weighted Haar unitary]\label{prop:haar}
There is a unitary \(w\in(A^\omega\cap A')^{\bar\alpha}\) such that,
for every \(a\in A\), \(\tau\in\T_\omega(A)\), and
\(f\in C(\mathbb T)\),
\begin{equation}\label{eq:haar}
 \tau(af(w))=\tau(a)\int_{\mathbb T}f\,d\mu,
\end{equation}
where \(\mathbb T=\{z\in\C:|z|=1\}\) and \(\mu\) is normalized
Haar measure.
\end{proposition}

\begin{proposition}[Equal trace projections]\label{prop:gamma}
The action \(\alpha\) has equivariant uniform property Gamma.
The projections in Definition~\ref{def:gamma} can be chosen to sum to \(1\).
\end{proposition}

\begin{proposition}[Binormal states and spectral shifts]\label{prop:inputs}
In this setting the following hold.
\begin{enumerate}[label=(\roman*)]
\item If a state $\Phi$ on $\mathbf B(\HH)$ satisfies
\[
 \Phi\circ\lambda=\Phi\circ\rho=\varphi,\qquad
 \Phi(e_N)=1,\qquad
 \Phi(f(X_M))=f(0)\quad(f\in C_0(\R)),
\]
then, for $a,b\in B$,
\begin{equation}\label{eq:binormal}
 \Phi(\lambda(a)\rho(b))=\langle a\Omega b,\Omega\rangle.
\end{equation}
\item For each $s\in\R$ there is a unital completely positive map
$\theta_s:\mathbf B(\HH)\to\mathbf B(\HH)$ such that
\begin{align}
 \theta_s(e_N)&=e_N,& \theta_s\circ\rho&=\rho,\label{eq:shift1}\\
 \theta_s\circ\lambda&=\lambda\circ\gamma_s\circ E_B,&
 \theta_s(f(X_M))&=f(X_M-s)\quad(f\in C_0(\R)).\label{eq:shift2}
\end{align}
These maps need not be normal.
\end{enumerate}
\end{proposition}

\begin{theorem}\label{thm:absolute}
For every type $\mathrm{III}_1$ factor $N$ with separable predual and every
faithful normal state $\varphi$ on $N$, one has $\B(N,\varphi)=\C1$.
\end{theorem}

\begin{proposition}[Uniform energy estimate]\label{prop:energy}
For every $\eta\in K$ there is a function
$\epsilon_\eta:(0,\infty)\to[0,\infty)$ with
$\epsilon_\eta(\delta)\to0$ as $\delta\downarrow0$ such that
\begin{equation}\label{eq:energy}
 \|(C-D_{\mathrm{all}})(\xi\otimes\eta)\|
 \le\epsilon_\eta(\delta)
\end{equation}
for every $n\ge1$, every $d_0,\ldots,d_n\in\R$, and every unit vector
$\xi\in H^{\otimes n}$ whose $S_n$-spectral support lies in an interval of
length $\delta$. The same function works for all these choices and for all
positions of the interval.
\end{proposition}

\begin{lemma}[The iterated kernel]\label{lem:kernel}
Formula~\eqref{eq:Zkernel} defines a unital completely positive map
$Z:\mathbf B(\HH)\to\mathbf B(H^{\otimes n})$, possibly nonnormal. It satisfies
\begin{align}
 Z(\lambda(a))&=Z(\rho(a))=\varphi(a)1\quad(a\in M),
 &Z(e_N)&=1,\label{eq:Zmarg}\\
 Z(f(X_M))&=f(S_n+d)\quad(f\in C_0(\R)).\label{eq:Zspectral}
\end{align}
For modular-analytic $a\in B$, put $a_+=\sigma_{i/2}(a)$, so that
$\Omega a_+=a\Omega$. Then, for $b\in B$ and
$\xi,\xi'\in H^{\otimes n}$,
\begin{equation}\label{eq:Zmixed}
 \langle Z(b^*\rho(a_+))\xi,\xi'\rangle
 =\langle C(\xi\otimes a\Omega),\xi'\otimes b\Omega\rangle.
\end{equation}
\end{lemma}

\begin{lemma}[Hybrid words and time averaging]\label{lem:hybrid}
The estimate \eqref{eq:energy} holds with the same modulus if any subset of
the $U_j$ is replaced by $D_j$, or if all $U_j$ are replaced by
$G_j=(U_j+D_j)/2$.
For every $\delta>0$ there is a probability density $p_\delta$ on $\R$ such
that, for every unit $\xi\in H^{\otimes n}$ without a spectral support
restriction,
\begin{equation}\label{eq:timeavg}
 \int_\R\|(C-D_{\mathrm{all}})(e^{itS_n}\xi\otimes\eta)\|^2
       p_\delta(t)\,dt\le\epsilon_\eta(\delta)^2.
\end{equation}
The statement includes the hybrid and averaged words.
\end{lemma}

\begin{theorem}\label{thm:UD}
For the operators in \eqref{eq:UD}, one has $U=D$.
\end{theorem}

\begin{proposition}\label{prop:corefixed}
If $N$ is a type $\mathrm{III}_1$ factor, then
\[
 \B(N\subset c(M),\varphi)^\gamma=N'\cap c(M).
\]
\end{proposition}

\begin{lemma}[An irreducible increasing-matrix subfactor]
\label{lem:irreducible-hyperfinite}
Every separable-predual \(\mathrm{II}_1\) factor \(M\) contains a unital
subfactor \(R\) with \(R'\cap M=\C1\), generated by an increasing sequence
of unital full matrix algebras whose sizes tend to infinity.
\end{lemma}

\begin{proposition}\label{prop:factor-representations}
Let $P\subset\B(K)$ be a unital factor acting on a separable Hilbert space.
For every $Y\in\B(K)$, every $h\ge1$, and every $X\in M_h(P)$,
\[
 \norm{[Y^{(h)},X]}
   \le C_{\mathrm{fac}}\,g_P(Y)\,\norm{X}.
\]
\end{proposition}

\begin{proposition}\label{prop:separable-estimate}
Let $P\subset\B(K)$ be any unital von Neumann algebra on a separable
Hilbert space.  Then
\[
 \norm{[Y^{(h)},X]}\le C\,g_P(Y)\,\norm{X}
 \qquad(Y\in\B(K),\ X\in M_h(P),\ h\ge1).
\]
\end{proposition}

\begin{proposition}\label{prop:all-derivations}
Let $A$ be a unital $C^*$-algebra and $\sigma:A\to\B(K)$ a unital
$*$-representation.  Every bounded $\sigma$-derivation
$\Delta:A\to\B(K)$ satisfies
\[
 \norm{\Delta}_{\mathrm{cb}}\le C\norm{\Delta}
\]
and is implemented by a bounded operator on $K$.
\end{proposition}

\begin{lemma}[The abelian corner and corner freeness]
\label{lem:dihedral-corner}
The algebra $p\mathcal C p$ is identified with the even functions on the
circle by
\begin{equation}
  \begin{gathered}
    p\mathcal C p
      =\{f(w)p:f\in L^\infty(\T,m),\ f(z)=f(z^{-1})\},\\
    \tau_p(f(w)p)=\int_{\T}f\,dm.
  \end{gathered}
  \label{eq:dihedral-corner}
\end{equation}
The map $f\mapsto f(w)p$ in this formula is a faithful normal unital
$*$-isomorphism onto the corner. Moreover, $pDp$ and $p\mathcal C p$
are free with respect to the normalized trace $\tau_p$.
\end{lemma}

\begin{lemma}[Free compression]
\label{lem:free-compression}
For $b=b^*\in p\mathcal C p$ with $\tau_p(b)=0$,
\begin{equation}
  E_{\mathcal C}(ebe)=u^2b,\qquad
  \|ebe\|\le2\sqrt u\,\|b\|_{2,\tau_p}+u\|b\|,
  \qquad u=\tau_p(e).
  \label{eq:free-compression}
\end{equation}
Here $E_{\mathcal C}$ is the trace-preserving conditional expectation
from $\cL$ onto $\mathcal C$.
\end{lemma}

\begin{theorem}[Uniform commutator estimate]\label{thm:universal}
There is an absolute constant \(C<\infty\) such that, for every complex
Hilbert space \(K\), every unital von Neumann algebra
\(P\subset\mathcal B(K)\), every \(Y\in\mathcal B(K)\), every integer
\(h\ge1\), and every \(X\in M_h(P)\),
\begin{equation}\label{eq:universal}
  \|[Y^{(h)},X]\|\le C\,g_P(Y)\,\|X\|.
\end{equation}
Here \(M_h(P)\) acts naturally on \(K^h\), and \([T,U]=TU-UT\).
\end{theorem}

\begin{lemma}[Row and column bounds]
\label{lem:row-column}
Every bounded rectangular derivation satisfies
\begin{equation}
 \max\{\|\Delta\|_{\mathrm{row}},\|\Delta\|_{\mathrm{col}}\}
       \le c_{\rm row}\|\Delta\|.
 \label{eq:rectangular-row-column}
\end{equation}
\end{lemma}

\begin{lemma}[Completely bounded rectangular derivations]
\label{lem:cb-implementation}
Let \(\sigma,\lambda,\Delta\) satisfy
\eqref{eq:rectangular-derivation}. If \(\Delta\) is completely bounded,
then some \(V\in\mathcal B(K,F)\) satisfies
\begin{equation}
 \Delta(a)=V\sigma(a)-\lambda(a)V\qquad(a\in A).
 \label{eq:rectangular-implementation}
\end{equation}
If \(d=\|\Delta\|>0\), one may choose
\[
 \|V\|\le d\bigl(1+\|\Delta\|_{\mathrm{cb}}/d\bigr)^2.
\]
\end{lemma}

\begin{lemma}[Implementation on a cyclic domain]
\label{lem:cyclic-implementation}
Let \(A\) be a unital \(C^*\)-algebra, let
\(\sigma:A\to\mathcal B(K)\) and
\(\lambda:A\to\mathcal B(F)\) be \(*\)-representations, and suppose
that \(\sigma\) has a cyclic vector. Every bounded rectangular
derivation \(\Delta:A\to\mathcal B(K,F)\) is completely bounded,
with
\begin{equation}
 \|\Delta\|_{\mathrm{cb}}\le4c_{\rm row}\|\Delta\|.
 \label{eq:cyclic-cb}
\end{equation}
Moreover there is \(V\in\mathcal B(K,F)\) such that
\begin{equation}
 \Delta(a)=V\sigma(a)-\lambda(a)V\quad(a\in A),\qquad
 \|V\|\le c_0\|\Delta\|.
 \label{eq:cyclic-implementation}
\end{equation}
\end{lemma}

\begin{lemma}[Full columns from a small corner]
\label{lem:full-column}
For every projection $r\in\cL$ with $\tau(r)\le t$, there is $b\in\cL$
with $b=rb$ such that
\begin{equation}
  \big\|(G-R_b)|_{Hr}\big\|\le c_0\epsilon.
  \label{eq:full-column}
\end{equation}
The same assertion holds for $G^*$.
\end{lemma}

\begin{lemma}[Propagation along repeated letters]
\label{lem:propagation}
For every $k\ge1$ and $v\in B=L^2(A_0)$,
\begin{equation}
  \big\|B_k(s^{\otimes k}\otimes v)
       -s^{\otimes k}\otimes B_0v\big\|
       \le 2c_0\epsilon\|v\|_2.
  \label{eq:propagation}
\end{equation}
This also holds with $B_k^*$ and $B_0^*$ in place of $B_k$ and $B_0$.
\end{lemma}

\begin{lemma}[Compression of the commutator]
\label{lem:compressed-commutator}
For every $h\in e\cL e$,
\begin{equation}
  \big\|[J,\iota^*L_h\iota]\big\|
       \le (1+4c_0)\epsilon\|h\|.
  \label{eq:compression-bound}
\end{equation}
\end{lemma}

\begin{theorem}[Free-product corner estimate]\label{thm:free-corner}
Let $\mathcal L=D*A_0$ be as above, let $t=1/N$ for an integer $N\geq2$,
and suppose that $G\in\mathcal B(L^2(\mathcal L))$ commutes with $L_D$.
Suppose that $\epsilon\geq0$ and
\begin{equation}\label{eq:free-corner-hypothesis}
  \|[G,L_x]\|\leq\epsilon\|x\|
  \qquad
  (x\in e\mathcal L e,
   \ e\in D\text{ a projection with }\tau(e)=t).
\end{equation}
If $s=s^*=s^{-1}\in A_0$ and $\tau(s)=0$, then
\begin{equation}\label{eq:free-corner-conclusion}
 \left\|P_{L^2(A_0)}[G,L_s]\big|_{L^2(A_0)}\right\|
       \leq c_1\epsilon,
 \qquad c_1=6\pi^2(1+4c_0).
\end{equation}
\end{theorem}

\begin{lemma}\label{lem:free-factor}
One has $D'\cap\mathcal L=\mathbb C1$.  In particular, $\mathcal L$ is a
${\rm II}_1$ factor.
\end{lemma}

\begin{lemma}[Word structure]\label{lem:word-structure}
The symmetrized operator $G$ preserves every level $\mathcal H_k$
in \eqref{eq:word-decomposition}.  There are operators
$B_k\in\mathcal B(J_k)$, with $\|B_k\|\leq\|G\|$, such that, for
all $d_0\in E$, $x\in E^\circ$, and $\alpha\in J_k$,
\begin{equation}\label{eq:repeated-letter}
 \begin{aligned}
 G(d_0\otimes x^{\otimes k}\otimes\alpha)
     &=d_0\otimes x^{\otimes k}\otimes B_k\alpha,\\
 G^*(d_0\otimes x^{\otimes k}\otimes\alpha)
     &=d_0\otimes x^{\otimes k}\otimes B_k^*\alpha.
 \end{aligned}
\end{equation}
These are identities in the full space $L^2(\mathcal L)$.
The operators $B_k$ are independent of the repeated letter $x$;
in particular, $x$ may be any complex centered $L^2$ vector.
\end{lemma}

\begin{proposition}\label{prop:circle}
There are unitary representations $\pi_z:F\to\B(K)$, indexed by
$z\in\mathbb T$, and operators $A_k(g)\in\B(K)$, indexed by
$k\in\mathbb Z$ and $g\in F$, such that
\begin{align}
 \pi_z(g)&=\sum_{k\in\mathbb Z}z^kA_k(g),
 &\sup_{g\in F}\|A_k(g)\|&\leq c_k,
 &c_k&=\mathbf 1_{\{k=0\}}+\frac{2t^{|k|}}{1-t},
 \label{eq:fourier}\\
 \pi_z(s_j)&\xrightarrow[j\to\infty]{\WOT}tzp_e.
 \label{eq:circle-limit}
\end{align}
The series in \eqref{eq:fourier} converges absolutely in operator norm,
uniformly in $g$ and $z$, and
\begin{equation}\label{eq:moments}
 S_0:=\sum_{k\in\mathbb Z}c_k<\infty,
 \qquad S_1:=\sum_{k\in\mathbb Z}|k|c_k<\infty.
\end{equation}
\end{proposition}

\begin{proposition}\label{prop:near}
For the algebras in \eqref{eq:algebras},
\begin{equation}\label{eq:near-bound}
 \gamma(M,N)\leq C\|UV-VU\|,
 \qquad
 C:=\sum_{k,m,p,h\in\mathbb Z}
       c_kc_mc_pc_h|m-p|\,|h|<\infty.
\end{equation}
Moreover, for every $g\in G$,
\begin{equation}\label{eq:group-bound}
 \bigl\|W(\lambda(g)\otimes I_L)W^*
            -\lambda(g)\otimes f(g)\bigr\|
 \leq C\|UV-VU\|.
\end{equation}
The constant is independent of $D,U,V$.
\end{proposition}

\begin{theorem}[Nonsimple nuclear regularity]
\label{thm:main}
\label{intro:regularity}
Let $A$ be a separable nuclear complex $C^*$-algebra with no nonzero
elementary ideal subquotients. The following conditions are equivalent:
\begin{enumerate}
\item $\nucdim(A)<\infty$;
\item $A\cong A\otimes\Z$;
\item $\nucdim(A)\le1$.
\end{enumerate}
\end{theorem}

\begin{corollary}[Regularity and Cuntz-semigroup criteria]
\label{cor:regularity-cu}
Under the hypotheses of Theorem~\ref{thm:main}, let
$\iota_A:A\to A\otimes\Z$ be $\iota_A(a)=a\otimes1_\Z$.
The conditions of that theorem are also equivalent to each of the following:
\begin{enumerate}[label=\textup{(\roman*)}]
\item the canonical map $\Cu(\iota_A):\Cu(A)\to\Cu(A\otimes\Z)$ is
an isomorphism in $\mathbf{Cu}$;
\item there is an abstract isomorphism $\Cu(A)\cong\Cu(A\otimes\Z)$
in $\mathbf{Cu}$.
\end{enumerate}
The abstract isomorphism need not be induced by a $*$-homomorphism.
\end{corollary}

\begin{theorem}[Full signs in a finite maximal tensor power]
\label{thm:tensor-intro}
For every nonzero unital complex $C^*$-algebra $D$ with no characters,
there is a finite integer $n\ge1$ such that
$D^{\otimes_{\max}n}$ contains two full orthogonal positive elements.
\end{theorem}

\begin{lemma}[Trace bounds in a hereditary subalgebra]
 \label{model:corner-traces}
Let $P,b\in A_+$ be contractions, and suppose that
$[P]\leq K[b]$ for a finite positive integer $K$.  If $\tau$ is a
lower semicontinuous extended trace with $d_\tau(b)<\infty$, then
its restriction to $D=\her(P)$ extends to a bounded positive linear
functional satisfying
\begin{equation}
 \label{model:corner-bound}
 \|\tau|_D\|\leq d_\tau(P)\leq Kd_\tau(b).
\end{equation}
Consequently, for $y,z\in D_+$,
\begin{equation}
 \label{model:corner-error}
 |\tau(y)-\tau(z)|
    \leq \|y-z\|K d_\tau(b).
\end{equation}
\end{lemma}

\begin{lemma}[Finite ideal slicing]
 \label{model:slicing}
Fix $m,N\geq1$, and let
$\mathcal T=\{1,\ldots,N\}^m$.  For every $t\in\mathcal T$ and
$S\subseteq\{1,\ldots,m\}$, there are positive contractions
$(P_{S,t,i})_{i\geq1}$ in $A$ with the following properties.
\begin{enumerate}
 \item For fixed $t,i$, the family $(P_{S,t,i})_S$ is orthogonal;
 in particular, $\sum_S P_{S,t,i}\leq1$.
 \item For every $a\in A$,
 $\|[P_{S,t,i},a]\|\to0$.  If $1\leq j\leq m$ and $j\notin S$, then
 \[
  \|P_{S,t,i}^{1/2}x_jP_{S,t,i}^{1/2}\|\longrightarrow0.
 \]
 \item If $j\in S$, then $P_{S,t,i}\in I_j$, and there is a finite
 positive integer $K_{S,t,i,j}$ such that
 \begin{equation}
  \label{model:finite-rank-bound}
  [P_{S,t,i}]\leq K_{S,t,i,j}[b_j].
 \end{equation}
 \item For every $a\in A$,
 \begin{equation}
  \label{model:slicing-approximation}
  \limsup_{i\to\infty}
  \left\|\frac1{N^m}\sum_{t\in\mathcal T}\sum_S
     P_{S,t,i}^{1/2}aP_{S,t,i}^{1/2}-a\right\|
  \leq\frac mN\|a\|.
 \end{equation}
\end{enumerate}
\end{lemma}

\begin{lemma}\label{supplies:copies}
For every integer $m\geq2$ there are a positive contraction
$D_m\in\Z$ of norm one, contractions $v_{m,1},\ldots,v_{m,m}\in\Z$,
and a finite positive integer $K_m$ such that
\begin{equation}\label{supplies:copy-relations}
 v_{m,r}^*v_{m,s}=\delta_{rs}D_m,
 \qquad
 1=\sum_{l=1}^{K_m}y_{m,l}^*(D_m-1/2)_+y_{m,l}
\end{equation}
for suitable $y_{m,l}\in\Z$.
\end{lemma}

\begin{lemma}[The common part]\label{setup:common}
There is a positive contraction $e\in B_1$ such that, with $q=1-e$,
\begin{equation}\label{setup:common-equations}
 L(e)=0,\qquad
 [e,\pi(a)]=[e,\theta(a)]=0,\qquad
 q\theta(a)=q\pi(a)
 \quad(a\in A).
\end{equation}
In particular, if $h=\theta(1)$, then $qh=q$.
\end{lemma}

\begin{lemma}[Localized rank estimates]\label{trace:rank}
For each $j$ there are nonnegative numbers
$\varepsilon_{n,j}\to_\omega0$, independent of the trace, with the
following properties.  Let $\lambda$ be any lower semicontinuous
extended trace on $R$, and let $\tau=\lambda|_A$.  If
$d_\tau(b)<\infty$, then, for $i=0,1$ and $\eta>0$,
\begin{equation}\label{trace:small-rank}
 d_\lambda((u_{n,i}-\eta)_+)
   \leq\eta^{-1}\varepsilon_{n,j}d_\tau(b).
\end{equation}
If $\ell_n\leq1/4$, then, with no finiteness assumption,
\begin{equation}\label{trace:large-rank}
 d_\lambda((z_n-\gamma/16)_+)
   \geq(\gamma/16)d_\tau(b).
\end{equation}
\end{lemma}

\begin{lemma}\label{trace:copies}
For every positive integer $L$ there are contractions
$v_1,\ldots,v_L\in B$, represented entirely in the $\Z_2$ leg,
such that
\begin{equation}\label{trace:ultrapower-copies}
 v_l^*v_{l'}=\delta_{ll'}P\qquad(1\leq l,l'\leq L).
\end{equation}
In particular these elements commute with $B_1$, and hence with
$\pi(A)$ and $q$.
\end{lemma}

\begin{proposition}[A supporting map preserving ideals]\label{support:map}
There is a c.p.c. order-zero map $\widehat\theta\colon A\to B$
whose range commutes with the constant copy of $\Z_3$ and such that
\begin{align}
 h\widehat\theta(a)=\widehat\theta(a)h&=\theta(a),
       \qquad a\in A,\label{support:factorization}\\
 [e,\widehat\theta(a)]&=0,
 \qquad q\widehat\theta(a)=q\pi(a),\qquad a\in A,
       \label{support:common}\\
 e\widehat\theta(a'),\ e\pi(a')&\in\Ideal_B(\Psi(a')),
       \qquad a'\in A_+.
       \label{support:ideals}
\end{align}
\end{proposition}

\begin{proposition}[Packing the error part]\label{comm:packing}
For $i\in\{0,1\}$ and every positive contraction $c\in C_i$,
\begin{align}
 m[(c^{1/2}ec^{1/2})^{(i)}]&\leq[Q_0],
       &&m\in\N,\label{comm:small-part}\\
 [c^{(i)}]&\leq2[Q_0]
       &&\text{in }W(C).\label{comm:two-common}
\end{align}
\end{proposition}

\begin{corollary}\label{comm:fullness}
The elements $Q_0,Q_1$ and $H$ are full in $C$, and $C$ is full
in $M_2(B)$.
\end{corollary}

\begin{proposition}\label{comm:unperforated}
The ordered semigroup $W(C)$ is almost unperforated.
\end{proposition}

\begin{proposition}\label{conjugacy:functions}
The elements $h_0,h_1$ are totally full in $C$.  For every
$g\in C_0((0,1])_+$, the elements $g(h_0)$ and $g(h_1)$ are
Cuntz equivalent in $C$.
\end{proposition}

\begin{proposition}[Weighted unitary equivalence]\label{conjugacy:weighted}
Put $k^{[0]}=k$ and $k^{[1]}=1-k$, in the constant third leg.
There are unitaries $U_0,U_1\in M_2(B)$ such that
\begin{equation}\label{conjugacy:weighted-equation}
 U_i\bigl(k^{[i]}\theta(a)\bigr)^{(1)}U_i^*
   =\bigl(k^{[i]}\pi(a)\bigr)^{(0)},
 \qquad a\in A,\quad i=0,1.
\end{equation}
They can be chosen to commute with $\rho(A)$.
\end{proposition}

\begin{lemma}[Products in commuting factors]\label{lem:factors}
Let \(M_1,\ldots,M_n\subseteq\mathcal B(H)\) be mutually commuting unital von Neumann factors. If \(e_j\in M_j\) is positive and \(\|e_j\|=1\), then
\[
 \left\|\prod_{j=1}^ne_j\right\|=1.
\]
\end{lemma}

\begin{lemma}[Pure-state excision]\label{lem:excision}
Let \(E\) be a unital \(C^*\)-algebra and \(\rho\) a pure state. Given a finite set \(\mathcal F\subset E\) and \(\varepsilon>0\), there is a positive contraction \(f\in E\) with \(\|f\|=1\) such that
\[
 \|fxf-\rho(x)f^2\|<\varepsilon\qquad(x\in\mathcal F).
\]
\end{lemma}

\begin{lemma}\label{lem:nocharacters}
If \(A\ne0\) is separable, nowhere scattered, and has finite nuclear dimension, then \(F(A)\) has no characters.
\end{lemma}

\begin{lemma}[Commuting reindexed copies]\label{lem:reindex}
Let \(A\ne0\) be separable, and let \(D\subseteq F(A)\) be a separable unital subalgebra with the same unit. For every finite \(n\), there is a unital \(*\)-homomorphism
\[
 D^{\otimes_{\max}n}\longrightarrow F(A).
\]
\end{lemma}

\begin{theorem}\label{thm:main}
A countable discrete group is strongly Ulam stable if and only if it is
amenable.
\end{theorem}

\begin{lemma}[Sparse restrictions]\label{lem:sparse}
For every $0<\eta<1/4$ there is $0<\beta_0<1/16$ with the following property.
If $0<\beta\leq\beta_0$, then for every sufficiently large integer $m$
there are unit vectors $(a_x)_{x\in X}$ in $\mathbb R^m$, where
$|X|=2m$, and signs $f(x)\in\{1,-1\}$ such that:
\begin{enumerate}
\item the vectors with either sign form an orthonormal basis, and hence
\begin{equation}\label{eq:frame-cancellation}
 \sum_{x\in X} f(x)a_xa_x^*=0;
\end{equation}
\item if $S\subseteq X$ and $|S|\leq4\beta|X|$, the synthesis map
$F_S:\ell^2(S)\to\mathbb C^m$, $F_Se_x=a_x$, satisfies
\begin{equation}\label{eq:sparse-gram}
 \norm{F_S^*F_S-\id}\leq\eta.
\end{equation}
\end{enumerate}
Moreover, for every sufficiently large integer $n$ there is a real
orthogonal $n\times n$ matrix $O$ such that, on a set $Y$ of size $2n$,
\begin{equation}\label{eq:JZ}
 J=\begin{pmatrix}0&O\\ O^*&0\end{pmatrix},
 \qquad Z=\begin{pmatrix}\id&0\\0&-\id\end{pmatrix}
\end{equation}
satisfy
\begin{equation}\label{eq:sparse-J}
 \norm{P_SJP_T}\leq\eta
 \quad\text{whenever}\quad |S|,|T|\leq4\beta|Y|.
\end{equation}
In particular, $J^*=J$, $J^2=Z^2=\id$, $JZ=-ZJ$, and every diagonal
entry of $J$ is zero.
\end{lemma}

\begin{proposition}\label{prop:comparison}
There are numerical constants $C$ and $h_0>0$ such that, for the construction
of Section~\ref{sec:construction} with $h\le h_0$ and $0<\eta\le1/4$,
\begin{equation}\label{eq:comparison}
 \norm{V_{qp}^{\{p,q\}}-V_{qp}^{\{p,q,r\}}}
 \le Ch+CN\eta+CNh\eta
\end{equation}
for every three configurations $p,q,r$. The constants do not depend on
the cardinalities of any alphabets or on the configurations.
\end{proposition}

\begin{lemma}\label{lem:transport}
For all but a proportion $2N\beta$ of labels $i\in\cI$,
\begin{equation}\label{eq:transport-bound}
 \norm{\mu(s_i)u_i-r_i}\le CN\eta+CNh\eta.
\end{equation}
\end{lemma}

\begin{proposition}\label{prop:sparse-splitting}
Let \(G\) be countable and nonamenable, and fix \(S,d,\rho\) as in
\Cref{lem:contracting-average}. For every \(\ell\ge1\), list the products
of \(\ell\) elements of \(S\), with multiplicity, as
\(s_1,\ldots,s_n\), where \(n=d^\ell\), and put
\(r=\lceil n\rho^\ell\rceil\). There is a function
\(a:G\times\{1,\ldots,n\}\to\{0,1\}\) such that
\begin{equation}\label{eq:sparse-mask}
 \#\{i:a(x,i)=1\}\le r\quad(x\in G),\qquad
 \#\{i:a(ys_i^{-1},i)=0\}\le r\quad(y\in G).
\end{equation}
\end{proposition}

\begin{proposition}[Uniformly bounded conjugation differences]
\label{prop:uniform-differences}
Under \Cref{eq:weights-orientation-bounds}, the maps $U(g)$ in
\Cref{eq:weights-A-T-U} form a unitary representation of $G$,
and $A$ commutes with every $U(g)$.  Define
\[
 D(g)=T-U(g)TU(g)^{-1}\quad(g\in G).
\]
Then
\begin{equation}
\label{eq:uniform-difference-bound}
 \sup_{g\in G}\norm{D(g)}\le b_0^2=100.
\end{equation}
Moreover, $D(e)=0$ and
\begin{equation}
\label{eq:weights-cocycle}
 D(gh)=D(g)+U(g)D(h)U(g)^{-1}\quad(g,h\in G).
\end{equation}
\end{proposition}

\begin{lemma}\label{lem:commutant-cb}
For every unital von Neumann algebra $A\subseteq\B(H)$ and
$h\in\B(H)$,
\begin{equation}\label{eq:commutant-cb}
 \dist(h,A')\le\norm{\ad_h|_A}_{\cb}.
\end{equation}
Consequently $\dcb(A,B)\le\gamma$ implies $d(A',B')\le4\gamma$.
\end{lemma}

\begin{lemma}[Column estimate]\label{lem:column-commutator}
Let \(A\subseteq\B(H)\) be a unital \(C^*\)-algebra, let \(h\in\B(H)\),
and put \(\delta=\norm{\ad_h|_A}\). Then
\[
 \norm{([h,a_i])_i}_{\mathrm{col}}
 \le 8\delta\,\norm{(a_i)_i}_{\mathrm{col}}
 \qquad(a_1,\ldots,a_l\in A).
\]
\end{lemma}

\begin{corollary}[Sum of squared word bounds through one label]
\label{cor:through-label}
For every integer $N\geq1$ there is an integer $d_0(N)$ such that,
whenever $d\geq d_0(N)$, the constants \eqref{eq:fw-beta} satisfy
\begin{equation}\label{eq:fw-through-label}
 \max_{1\leq a\leq d}
 \sum_{\substack{W\text{ a multiset from }\{1,\ldots,d\}\\
                 |W|=r,\ a\in W}}
       \beta_W^2\leq64
 \qquad(1\leq r\leq N).
\end{equation}
Membership $a\in W$ here means that $a$ occurs at least once;
each multiset is counted once, regardless of that multiplicity.
In particular, for free copies as in \cref{lem:free-words}, the norm
bounds and \eqref{eq:fw-through-label} hold simultaneously through
length $N$ after choosing this one threshold for $d$.
\end{corollary}

\begin{lemma}
\label{lem:finite-neighbor}
If $M\subseteq\B(H)$ is a unital finite factor and $N\subseteq\B(H)$
is a von Neumann algebra with $d(M,N)<1/10$, then $N$ is a finite factor.
\end{lemma}

\begin{lemma}[Testing a bimodular operator on bounded algebra elements]
\label{lem:finite-ball-tests}
Let $M$ be a $\II_1$ factor and let $R=(\bigcup_jQ_j)''\subseteq M$
be as in \Cref{lem:irreducible-hyperfinite}.  If a bounded operator $V$
on $L^2(M,\tau)$ commutes with left and right multiplication by $R$, then
\[
 \norm{V}\le384\sup_{a,b\in M_1}
       \abs{\ip{Va\Omega}{b\Omega}}.
\]
\end{lemma}

\begin{lemma}[The orientation of a Jordan map into a factor]
\label{lem:jordan-orientation}
A surjective linear Jordan homomorphism between unital complex algebras,
whose target is a factor von Neumann algebra, is either a homomorphism
or an antihomomorphism.
\end{lemma}

\begin{lemma}[Amplification by common isometries]
\label{lem:common-infinite-amplification}
Let $M,N\subseteq\B(H)$ contain the same unital copy of $\B(\ell^2)$.
Then $\dcb(M,N)=d(M,N)$.
\end{lemma}

\begin{lemma}
\label{lem:infinite-commutant-bound}
For a separably acting properly infinite von Neumann algebra
$P\subset\B(H)$ and $h=h^*\in\B(H)$,
\[
 \dist(h,P')\le4\norm{\ad_h|_P}.
\]
\end{lemma}

\begin{lemma}[Uniform infinitesimal estimate]
\label{lem:local-normalizer-linear}
There is an absolute $K<\infty$ such that every separably acting
type $\III$ factor $P\subset\B(H)$ and every self-adjoint
$h\in\B(H)$ satisfy
\begin{equation}
 \dist(h,P+P')
 \le K\sup_{x\in P_1}\dist([h,x],P).
 \label{eq:normalizer-linear-bound}
\end{equation}
The sum $P+P'$ here is a linear subspace; no closedness assertion
about that sum is needed.
\end{lemma}

\begin{lemma}[Analytic extension of a frequency-preserving multiplier]
\label{lem:analytic-multiplier}
Suppose multiplication by a bounded field $B(t)$ on $L^2(\R,H)$ preserves
$P_0\mathcal K$.  Then it is the boundary field of a bounded, operator-norm
holomorphic function on the upper half-plane, given by
\begin{equation}\label{eq:analytic-poisson}
 B(t+ir)=\int_\R \frac{r}{\pi((t-s)^2+r^2)}B(s)\,ds,
 \qquad r>0.
\end{equation}
Its norm is at most $\mathop{\rm ess\,sup}_s\norm{B(s)}$.
For two such fields, and any constant $x\in\B(H)$, the extension of the
boundary product $B(s)xS(s)$ is $B(z)xS(z)$.
\end{lemma}

\begin{lemma}[Common-action fixed points]
\label{lem:core-fixed-points}
With this notation,
\begin{equation}\label{eq:core-fixed-description}
 C(P,U)=
 \bigl(P\barotimes\B(L^2(\R))\bigr)^\alpha,
 \qquad
 \alpha_s=\Ad(U_s\otimes\rho_s).
\end{equation}
For $(Q_a\xi)(t)=e^{iat}\xi(t)$, character conjugation
$\beta_a=\Ad(Q_a)$ preserves $C(P,U)$, and
\begin{equation}\label{eq:core-character-fixed}
 C(P,U)^\beta=\pi(P).
\end{equation}
\end{lemma}

\begin{lemma}\label{lem:separable-tests}
Let $M,N\subseteq\B(H)$ be unital von Neumann algebras, and let
$g>d(M,N)$.  Given finite sets $E\subseteq M$, $F\subseteq N$, and
$V\subseteq H$ with $V$ containing a nonzero vector, there are
separable unital $C^*$-subalgebras $A\subseteq M$, $B\subseteq N$
and a nonzero separable closed subspace $K\subseteq H$ such that:
\begin{enumerate}[label=\textup{(\roman*)},leftmargin=*]
 \item $E\subseteq A$, $F\subseteq B$, and $V\subseteq K$;
 \item $K$ reduces both $A$ and $B$;
 \item $d(A,B)<g$ and
 \[
  d\bigl((A|_K)'',(B|_K)''\bigr)<g.
 \]
\end{enumerate}
Here the restriction homomorphisms are not required to be faithful.
\end{lemma}
